### ✅ **4. `HoenScannerApplication.java` (modified)**

```java
package com.hoenscanner;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.hoenscanner.model.SearchResult;
import com.hoenscanner.resources.SearchResource;
import io.dropwizard.Application;
import io.dropwizard.setup.Bootstrap;
import io.dropwizard.setup.Environment;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class HoenScannerApplication extends Application<HoenScannerConfiguration> {

    public static void main(final String[] args) throws Exception {
        new HoenScannerApplication().run(args);
    }

    @Override
    public String getName() {
        return "HoenScanner";
    }

    @Override
    public void initialize(final Bootstrap<HoenScannerConfiguration> bootstrap) {
        // nothing to do yet
    }

    @Override
    public void run(final HoenScannerConfiguration configuration,
                    final Environment environment) throws Exception {

        ObjectMapper mapper = new ObjectMapper();
        List<SearchResult> searchResults = new ArrayList<>();

        InputStream carStream = getClass().getClassLoader().getResourceAsStream("rental_cars.json");
        InputStream hotelStream = getClass().getClassLoader().getResourceAsStream("hotels.json");

        List<SearchResult> cars = Arrays.asList(mapper.readValue(carStream, SearchResult[].class));
        List<SearchResult> hotels = Arrays.asList(mapper.readValue(hotelStream, SearchResult[].class));

        searchResults.addAll(cars);
        searchResults.addAll(hotels);

        // Register resource
        environment.jersey().register(new SearchResource(searchResults));
    }
}
```

